from test.unit.rules import BaseRuleTestCase
from cfnlint import ConfigMixIn
from cfnlint.runner import TemplateRunner
from cfnlint.rules import Rules
from cfnlint.config import _DEFAULT_RULESDIR


class TestTypeConditionsAvailability(BaseRuleTestCase):
    def setUp(self):
        super(TestTypeConditionsAvailability, self).setUp()
        self.rules = Rules.create_from_directory(_DEFAULT_RULESDIR)

    def test_e3006_not_suppressed_by_condition_cn(self):
        template = {
            "AWSTemplateFormatVersion": "2010-09-09",
            "Conditions": {
                "NotChina": {
                    "Fn::Not": [
                        {
                            "Fn::Or": [
                                {"Fn::Equals": [{"Ref": "AWS::Region"}, "cn-north-1"]},
                                {"Fn::Equals": [{"Ref": "AWS::Region"}, "cn-northwest-1"]},
                            ]
                        }
                    ]
                }
            },
            "Resources": {
                "GAListener": {
                    "Type": "AWS::GlobalAccelerator::Listener",
                    "Condition": "NotChina",
                }
            },
        }

        runner = TemplateRunner(
            filename=None,
            template=template,
            config=ConfigMixIn(regions=["cn-north-1"], include_checks=["E"]),
            rules=self.rules,
        )
        matches = list(runner.run())

        # Ensure E3006 is raised for the GAListener resource path regardless of Condition
        assert any(
            m.rule.id == "E3006" and "Resources/GAListener" in getattr(m, "path_string", "")
            for m in matches
        ), f"Expected E3006 for Resources/GAListener in cn-north-1. Got: {[ (m.rule.id, getattr(m,'path_string','')) for m in matches ]}"
